const text = $input.first().json.message?.content || $input.first().json.text || '';
try {
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  const data = JSON.parse(jsonMatch[0]);
  data.employee_name = $('Receipt Upload Webhook').first().json.body?.employee_name || 'Unknown';
  data.department = $('Receipt Upload Webhook').first().json.body?.department || 'General';
  data.receipt_id = 'RCP-' + Date.now().toString(36).toUpperCase();
  return [data];
} catch(e) {
  return [{error: 'Failed to parse receipt', raw: text}];
}

